design.css:
/* A quiet, neutral workspace inspired by Baseline's default layout. */
:scope {
  --tigrana-panel-gap: 8px;
  --tigrana-workspace-inset: 8px;
  --tigrana-panel-radius: 10px;
  --tigrana-panel-shadow: none;
  --tigrana-workspace-background: var(--surface-muted);
}
.app-frame { padding-top: 4px; }
.app-titlebar { background: var(--surface-muted); border-bottom: 0; }
.note-tab { border-radius: 8px; }
.folder-pane, .notes-pane, .unified-tree-pane, .main-pane, .right-sidebar { border: 0; }
.pane-header { color: var(--tigrana-text); text-transform: none; font-size: 13px; letter-spacing: 0; padding: 14px; border-bottom: 0; }
.pane-header strong { font-weight: 500; }
.topbar { border-bottom: 0; }
.section-view-folder-pane .folder-row { border-radius: 0; margin-right: 6px; }
.note-title-input { font-weight: 650; letter-spacing: -0.025em; }
.ProseMirror h1, .ProseMirror h2, .ProseMirror h3 { font-weight: 600; letter-spacing: -0.015em; }
.ProseMirror a { color: var(--tigrana-editor-text); text-decoration: underline; text-underline-offset: 3px; }
.ProseMirror blockquote { border-left: 3px solid var(--tigrana-border); padding: 10px 16px; background: var(--surface-soft); }
.ProseMirror pre, .ProseMirror table { border: 1px solid var(--tigrana-border); }
.pane-resizer { background: transparent; }
.pane-resizer::after { opacity: 0; }
.pane-resizer:hover::after, .pane-resizer:focus-visible::after { opacity: 1; }
